  private function target(string $relative):string{$relative=str_replace('\\\\','/',$relative);if($relative===''||str_starts_with($relative,'/')||preg_match('/(^|\\/)\\.\\.(\\/|$)/',$relative)||str_contains($relative,"\\0"))throw new InvalidArgumentException('Path must be relative and remain inside the DCP workspace.');$path=$this->root.'/'.$relative;$parent=dirname($path);while(!is_dir($parent)&&$parent!==$this->root)$parent=dirname($parent);$real=realpath($parent);if($real===false||($real!==$this->root&&!str_starts_with($real,$this->root.DIRECTORY_SEPARATOR)))throw new RuntimeException('Path escapes the DCP workspace.');return $path;}
